     1	package hotel.reservations;
     2	
     3	import hotel.documents.ReservationReceipt;
     4	import hotel.messages.EmailSender;
     5	import hotel.rooms.Room;
     6	import hotel.rooms.Rooms;
     7	import java.math.BigDecimal;
     8	
     9	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
    10	public final class ReservationService {
    11	
    12	    static final String HOTEL_NAME = "Pousada Maré Alta";
    13	
    14	    private final Rooms rooms;
    15	    private final ReservationStore store;
    16	    private final PriceCalculator priceCalculator;
    17	    private final EmailSender emailSender;
    18	
    19	    public ReservationService(
    20	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
    21	        this.rooms = rooms;
    22	        this.store = store;
    23	        this.priceCalculator = priceCalculator;
    24	        this.emailSender = emailSender;
    25	    }
    26	
    27	    public synchronized Reservation create(NewReservation request) {
    28	        if (!request.checkOut().isAfter(request.checkIn())) {
    29	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    30	        }
    31	        if (request.guests() < 1) {
    32	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    33	        }
    34	        request.ratePlan().policy().checkBookable(request);
    35	        Room room = rooms.find(request.roomNumber())
    36	                .orElseThrow(() -> new HotelException(
    37	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    38	        if (request.guests() > room.capacity()) {
    39	            throw new HotelException(
    40	                    ErrorCode.CAPACITY_EXCEEDED,
    41	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    42	        }
    43	        boolean roomTaken = store.all().stream()
    44	                .filter(existing -> existing.status() != ReservationStatus.CANCELLED)
    45	                .anyMatch(existing -> existing.overlaps(room.number(), request.checkIn(), request.checkOut()));
    46	        if (roomTaken) {
    47	            throw new HotelException(
    48	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    49	        }
    50	        Price price = priceCalculator.calculate(room, request);
    51	        Reservation reservation = new Reservation(store.nextId(), request, price);
    52	        store.save(reservation);
    53	        return reservation;
    54	    }
    55	
    56	    public Reservation find(long reservationId) {
    57	        return store.find(reservationId)
    58	                .orElseThrow(() -> new HotelException(
    59	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
    60	    }
    61	
    62	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
    63	    public synchronized Reservation confirm(long reservationId) {
    64	        Reservation reservation = find(reservationId);
    65	        if (reservation.status() != ReservationStatus.PENDING) {
    66	            throw notAllowed(reservation, "confirm");
    67	        }
    68	        reservation.confirmPayment();
    69	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
    70	        emailSender.send(
    71	                reservation.guest().email(),
    72	                "Reserva confirmada - " + HOTEL_NAME,
    73	                confirmationEmailBody(reservation, receipt));
    74	        return reservation;
    75	    }
    76	
    77	    /**
    78	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
    79	     * reservation was never paid, so nothing comes back).
    80	     */
    81	    public synchronized Reservation cancel(long reservationId) {
    82	        Reservation reservation = find(reservationId);
    83	        if (reservation.status() != ReservationStatus.PENDING
    84	                && reservation.status() != ReservationStatus.CONFIRMED) {
    85	            throw notAllowed(reservation, "cancel");
    86	        }
    87	        BigDecimal refund = reservation.ratePlan().policy().refund(reservation.amountPaid());
    88	        reservation.cancel(refund);
    89	        return reservation;
    90	    }
    91	
    92	    public synchronized Reservation checkIn(long reservationId) {
    93	        Reservation reservation = find(reservationId);
    94	        if (reservation.status() != ReservationStatus.CONFIRMED) {
    95	            throw notAllowed(reservation, "check in");
    96	        }
    97	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
    98	        return reservation;
    99	    }
   100	
   101	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
   102	    public synchronized ReservationReceipt checkOut(long reservationId) {
   103	        Reservation reservation = find(reservationId);
   104	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
   105	            throw notAllowed(reservation, "check out");
   106	        }
   107	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
   108	        return new ReservationReceipt(reservation, roomOf(reservation));
   109	    }
   110	
   111	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
   112	    public ReservationReceipt receiptCopy(long reservationId) {
   113	        Reservation reservation = find(reservationId);
   114	        if (!reservation.isPaid()) {
   115	            throw notAllowed(reservation, "issue a receipt for");
   116	        }
   117	        return new ReservationReceipt(reservation, roomOf(reservation));
   118	    }
   119	
   120	    private Room roomOf(Reservation reservation) {
   121	        return rooms.find(reservation.roomNumber()).orElseThrow();
   122	    }
   123	
   124	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
   125	        return "Olá, " + reservation.guest().name() + "!\n\n"
   126	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
   127	                + receipt.text() + "\n"
   128	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
   129	                + "Até breve!\n";
   130	    }
   131	
   132	    private static HotelException notAllowed(Reservation reservation, String operation) {
   133	        return new HotelException(
   134	                ErrorCode.OPERATION_NOT_ALLOWED,
   135	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
   136	    }
   137	}

